function projectStoryMarkup(id){const story=projectStories[id],project=projectData[id];return `<article class="project-story"><div class="story-toolbar"><button class="back-button tactile" data-open="work">← All projects</button><span class="story-status ${id==='goprava'?'ongoing':''}"><i></i>${story.status}</span></div><p class="panel-eyebrow">${story.category}</p><h2 class="panel-title" id="panel-title">${project.name}<span class="soft-text">.</span></h2><p class="panel-lead story-summary">${story.summary}</p>${story.image?`<button class="story-preview tactile" data-lightbox="${id}" aria-label="View larger screenshot of ${project.name}"><span class="preview-chrome"><i></i><i></i><i></i><span>${id==='tourfixer'?'tourfixer.uz':'advoai.uz'}</span><b>↗</b></span><img src="${story.image}" alt="${story.alt}" width="870" height="716" loading="eager" decoding="async"><span class="preview-caption">${story.caption}<b>Tap to look closer ↗</b></span></button>`:`<div class="work-in-progress"><div class="wip-orb">G↗</div><div><span class="story-status ongoing"><i></i>In progress</span><h3>A little patience.<br>Something is taking shape.</h3><p>The next chapter is still being built.</p></div><span class="wip-spark">✧</span></div>`}<div class="story-intro"><span class="section-kicker">The idea</span><p>${story.idea}</p></div><div class="story-chapters">${story.details.map(([title,body],i)=>`<section><span class="chapter-number">0${i+1}</span><div><h3>${title}</h3><p>${body}</p></div></section>`).join('')}</div><div class="story-footer"><div class="detail-tags">${story.tags.map(t=>`<span>${t}</span>`).join('')}</div><a class="panel-link tactile" href="${story.link}" target="_blank" rel="noopener">${story.linkText}${icon('arrow')}</a></div>${id==='tourfixer'?`<button class="inline-discovery tactile" data-open="travel">${icon('plane')} Take a little trip around the globe <span>↗</span></button>`:''}</article>`}
